body { font: 16px/1.5 sans-serif; }
.theme {
  --surface: #ffffff;
  --texte: #172a3a;
  --secondaire: #334155;
  --accent: #164e63;
  --ligne: #475569;
  --action-fond: #164e63;
  --action-texte: #ffffff;
  --focus: #9a3412;
  color: var(--texte);
  background-color: var(--surface);
  padding: 16px;
}
.theme[data-theme="nuit"] {
  --surface: #172a3a;
  --texte: #f8fafc;
  --secondaire: #cbd5e1;
  --accent: #bae6fd;
  --ligne: #94a3b8;
  --action-fond: #bae6fd;
  --action-texte: #172a3a;
  --focus: #fbbf24;
}
.theme .resume { color: var(--secondaire); }
.theme .lien { color: var(--accent); text-decoration: underline; }

